@dataclass
class Literal: pos: Pos; value: Any; is_float: bool=False
@dataclass
class Var: pos: Pos; name: str
@dataclass
class SelfVar: pos: Pos
@dataclass
class Unary: pos: Pos; op: str; expr: Any
@dataclass
class Binary: pos: Pos; left: Any; op: str; right: Any
@dataclass
class ArrayLit: pos: Pos; items: List[Any]
@dataclass
class DictLit: pos: Pos; items: List[Tuple[str,Any,Pos]]
@dataclass
class IfExpr: pos: Pos; cond: Any; then_body: List[Any]; else_body: List[Any]
@dataclass
class FunctionExpr: pos: Pos; params: List[str]; body: List[Any]
@dataclass
class Call: pos: Pos; callee: Any; args: List[Any]
