        self.msg = msg

class ReturnEx(Exception):
    def __init__(self, value): self.value = value
class BreakEx(Exception): pass
class ExitEx(Exception):
    def __init__(self, code): self.code=code

# ----------------------------- values -----------------------------

class NilType: pass
NIL = None

@dataclass(frozen=True)
class Char:
    ch: str

@dataclass
class HError:
    message: str
    data: Any = None
    pos: Optional[Pos] = None

class Cell:
    def __init__(self, value=NIL): self.value=value

class Env:
    def __init__(self, parent=None):
        self.parent=parent
        self.vars: Dict[str,Cell] = {}
    def declare(self, name, value=NIL):
        c=Cell(value); self.vars[name]=c; return c
    def find_cell(self, name):
        e=self
        while e is not None:
            if name in e.vars: return e.vars[name]
            e=e.parent
        return None
    def get(self, name):
        c=self.find_cell(name)
        return c.value if c else NIL
    def set(self, name, val):
        c=self.find_cell(name)
        if c is None:
            c=self.declare(name,val)
        else:
            c.value=val

@dataclass
class UserFunction:
    params: List[str]
    body: List[Any]
    env: Env
    pos: Pos
    name: Optional[str]=None
    def call(self, interp, args, pos, receiver=NIL):
        if len(args) != len(self.params):
            panic(pos, f"incorrect amount of function parameters -- supplied {len(args)}, expected {len(self.params)}")
        local=Env(self.env)
        for p,v in zip(self.params,args): local.declare(p,v)
        # self exists for every function; the analyzer only allows it inside functions.
        local.declare('self', receiver)
        try:
            return interp.eval_block(self.body, local)
        except ReturnEx as r:
            return r.value

@dataclass
class BuiltinFunction:
    name: str
    func: Any
    arity: Optional[int]=None
    variadic: bool=False
    def call(self, interp, args, pos, receiver=NIL):
        if self.arity is not None and len(args)!=self.arity:
            panic(pos, f"incorrect amount of function parameters -- supplied {len(args)}, expected {self.arity}")
        return self.func(interp,args,pos)
    def __repr__(self): return f"{self.name}<impl>"

# ----------------------------- formatting -----------------------------

def pos_of(node):
    return getattr(node,'pos', Pos('<unknown>',1,0))

def panic(pos: Pos, msg: str):
    raise PanicEx(pos,msg)

def type_name(v):
    if v is NIL: return 'nil'
    if isinstance(v,bool): return 'bool'
    if isinstance(v,int) and not isinstance(v,bool): return 'int'
    if isinstance(v,float): return 'float'
    if isinstance(v,Char): return 'char'
    if isinstance(v,str): return 'string'
    if isinstance(v,list): return 'array'
    if isinstance(v,dict): return 'dict'
    if isinstance(v,(UserFunction,BuiltinFunction)): return 'function'
    if isinstance(v,HError): return 'error'
    if isinstance(v,AsyncTask): return 'dict'
    return type(v).__name__

def esc_str(s: str, quote='"'):
    out=''
    for ch in s:
        if ch=='\n': out+='\\n'
        elif ch=='\t': out+='\\t'
        elif ch=='\0': out+='\\0'
        elif ch=='\\': out+='\\\\'
        elif ch==quote: out+='\\'+quote
        elif ch=='\r': out+='\\r'
        else: out+=ch
    return out

def float_cmd(v: float):
    if math.isfinite(v) and v == int(v): return f"{v:.1f}"
    return repr(v)

def ast_num(v, is_float=False):
    if is_float:
        if v == int(v): return str(int(v))
        return repr(v)
    return str(v)

def value_str(v):
    if v is NIL: return 'nil'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int) and not isinstance(v,bool): return str(v)
    if isinstance(v,float): return float_cmd(v)
    if isinstance(v,Char): return v.ch
    if isinstance(v,str): return '"'+esc_str(v)+'"'
    if isinstance(v,list): return '[ ' + ', '.join(value_str(x) for x in v) + ' ]'
    if isinstance(v,dict):
        parts=[]
        for k,val in v.items(): parts.append(f"{value_str(k)}: {value_str(val)}")
        return '@[ ' + ', '.join(parts) + ' ]'
    if isinstance(v,UserFunction): return f"function<{v.pos.display()}>"
    if isinstance(v,BuiltinFunction): return f"{v.name}<impl>"
    if isinstance(v,HError): return f"error: {value_str(v.message)} ({value_str(v.data)})"
    if isinstance(v,AsyncTask): return '@[ "join": function ]'
    return str(v)

def to_string_value(v):
    if v is NIL: return 'nil'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int) and not isinstance(v,bool): return str(v)
    if isinstance(v,float): return float_cmd(v)
    if isinstance(v,Char): return v.ch
    if isinstance(v,str): return v
    if isinstance(v,list): return '[ ' + ', '.join(value_str(x) for x in v) + ' ]'
    if isinstance(v,dict):
        return '@[ ' + ', '.join(f'{value_str(k)}: {value_str(val)}' for k,val in v.items()) + ' ]'
    if isinstance(v,HError): return value_str(v)
    return value_str(v)

def command_atom(v,pos):
    if v is NIL: return ''
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int) and not isinstance(v,bool): return str(v)
    if isinstance(v,float): return float_cmd(v)
    if isinstance(v,Char): return v.ch
    if isinstance(v,str): return v
    panic(pos, f"value ({value_str(v)}) has unexpected type, expected nil, bool, int, float, byte or string")

def expect_type(v, names, pos):
    if isinstance(names,str): names=[names]
    ok=False
    for n in names:
        if n=='nil' and v is NIL: ok=True
        elif n=='bool' and isinstance(v,bool): ok=True
        elif n=='int' and isinstance(v,int) and not isinstance(v,bool): ok=True
        elif n=='float' and isinstance(v,float): ok=True
        elif n in ('byte','char') and isinstance(v,Char): ok=True
        elif n=='string' and isinstance(v,str): ok=True
        elif n=='array' and isinstance(v,list): ok=True
        elif n=='dict' and isinstance(v,dict): ok=True
        elif n=='function' and isinstance(v,(UserFunction,BuiltinFunction)): ok=True
        elif n=='error' and isinstance(v,HError): ok=True
    if not ok:
        panic(pos, f"value ({value_str(v)}) has unexpected type, expected {' or '.join(names)}")
    return v

# ----------------------------- lexer -----------------------------

@dataclass
class Token:
    typ: str
    val: Any
    pos: Pos
    text: str=''

@dataclass
class CmdSegment:
    kind: str # lit,var
    val: str
    quoted: bool=False
    pos: Optional[Pos]=None

@dataclass
class CmdWord:
    segments: List[CmdSegment]
    raw_display: str
    any_quoted: bool=False
    def ast_display(self):
        s=''
        for seg in self.segments:
            if seg.kind=='lit': s+=seg.val
            else: s+='${'+seg.val+'}'
        return '"'+esc_str(s)+'"'

class Lexer:
    KEYWORDS={'let','function','if','then','else','elseif','end','while','do','for','in','break','return','true','false','nil','and','or','not','self'}
    SIMPLE=set('()+-*/%,.:=[]<>')
    def __init__(self, source, filename):
        self.s=source; self.file=filename; self.i=0; self.line=1; self.col=0
        self.tokens=[]; self.errors=[]; self.lex_items=[]
    def pos(self): return Pos(self.file,self.line,self.col)
    def eof(self): return self.i>=len(self.s)
    def peek(self,n=0): return self.s[self.i+n] if self.i+n<len(self.s) else ''
    def adv(self):
        ch=self.peek(); self.i+=1
        if ch=='\n': self.line+=1; self.col=0
        else: self.col+=1
        return ch
    def add(self,typ,val=None,pos=None,text=None):
        if pos is None: pos=self.pos()
        if val is None: val=text if text is not None else typ
        tok=Token(typ,val,pos,text or str(val))
        self.tokens.append(tok); self.lex_items.append(tok); return tok
    def err(self,pos,msg,lexical=True):
        self.errors.append(Diag(pos,msg,lexical))
        # token-like item for lex stream
        self.lex_items.append(Diag(pos,msg,lexical))
    def scan(self):
        while not self.eof():
            ch=self.peek()
            if ch.isspace(): self.adv(); continue
            if ch=='#':
                while not self.eof() and self.peek()!='\n': self.adv()
                continue
            p=self.pos()
            if ch.isalpha() or ch=='_':
                ident=''
                while self.peek().isalnum() or self.peek()=='_': ident+=self.adv()
                typ=ident.upper() if ident in self.KEYWORDS else 'IDENT'
                self.add(typ,ident,p,ident); continue
            if ch.isdigit():
                self.scan_number(); continue
            if ch=='"': self.scan_string(False); continue
            if ch=="'": self.scan_string(True); continue
            if ch=='@':
                self.adv()
                if self.peek()=='[':
                    self.adv(); self.add('AT_LBRACKET','@[',p,'@[')
                else:
                    self.err(p, f"unexpected '@'.")
                continue
            if ch=='$':
                self.adv()
                if self.peek()=='{':
                    self.adv(); self.add('CAPTURE_LBRACE','${',p,'${'); self.scan_command(); continue
                else:
                    self.err(p, "unexpected '$'."); continue
            if ch=='&':
                self.adv()
                if self.peek()=='{':
                    self.adv(); self.add('ASYNC_LBRACE','&{',p,'&{'); self.scan_command(); continue
                else:
                    self.err(p, "unexpected '&'."); continue
            if ch=='{':
                self.adv(); self.add('LBRACE','{',p,'{'); self.scan_command(); continue
            two=self.s[self.i:self.i+2]
            if two in ('==','!=','<=','>=','++'):
                self.adv(); self.adv(); self.add(two,two,p,two); continue
            if ch in self.SIMPLE:
                self.adv(); self.add(ch,ch,p,ch); continue
            if ch==';' or ch=='|' or ch=='}':
                self.adv(); self.err(p, f"unexpected '{ch}'.");
                # add token for parser recovery
                self.tokens.append(Token(ch,ch,p,ch))
                continue
            self.adv(); self.err(p, f"unexpected '{escape_unexpected(ch)}'.")
        self.tokens.append(Token('EOF','',Pos(self.file,self.line,self.col),'EOF'))
        return self.tokens,self.errors
    def scan_number(self):
        p=self.pos(); raw=''
        while self.peek().isdigit(): raw+=self.adv()
        is_float=False
        if self.peek()=='.' and self.i+1<len(self.s) and self.s[self.i+1].isdigit():
            is_float=True; raw+=self.adv()
            while self.peek().isdigit(): raw+=self.adv()
        if self.peek() in ('e','E'):
            # original accepts unsigned exponent only
            is_float=True; raw+=self.adv()
            if not self.peek().isdigit():
                # let later chars be unexpected-ish; still try
                pass
            while self.peek().isdigit(): raw+=self.adv()
        try:
            if is_float:
                val=float(raw)
                disp=ast_num(val,True)
                self.add('NUMBER',(val,True),p,disp)
            else:
                val=int(raw)
                self.add('NUMBER',(val,False),p,str(val))
        except Exception:
            self.add('NUMBER',(0,False),p,'0')
    def scan_string(self,is_char):
        quote="'" if is_char else '"'; p=self.pos(); self.adv()
        val=''; raw=quote; invalid=False; inv_msg=None; inv_pos=None
        while not self.eof():
            ch=self.adv(); raw+=ch
            if ch==quote: break
            if ch=='\n':
                self.err(Pos(self.file,self.line-1,0), "unexpected '\\n'."); break
            if ch=='\\':
                ep=self.pos(); nxt=self.adv(); raw+=nxt
                mp={'n':'\n','t':'\t','0':'\0','\\':'\\','"':'"',"'":"'"}
                if nxt in mp:
                    val+=mp[nxt]
                else:
                    invalid=True; inv_msg=f"invalid escape sequence '\\{nxt}'."; inv_pos=Pos(self.file, ep.line, ep.col-1)
                    val+='\0' if is_char else ''
            else:
                val+=ch
        if invalid: self.err(inv_pos,inv_msg)
        if is_char:
            if len(val)!=1:
                # mimic common recovery: keep first char or nul and complain near extra char
                if len(val)>1:
                    self.err(Pos(self.file,p.line,p.col+2), f"unexpected '{escape_unexpected(val[1])}'.")
                    val=val[0]
                else: val='\0'
            disp="'"+esc_str(val,"'")+"'"
            self.add('CHAR',Char(val),p,disp)
        else:
            disp='"'+esc_str(val)+'"'
            self.add('STRING',val,p,disp)
    def scan_command(self):
        while not self.eof():
            ch=self.peek()
            if ch.isspace(): self.adv(); continue
            if ch=='#':
                while not self.eof() and self.peek()!='\n': self.adv()
                continue
            p=self.pos()
            if ch=='}': self.adv(); self.add('RBRACE','}',p,'}'); return
            if ch==';': self.adv(); self.add('CMD_SEMI',';',p,';'); continue
            if ch=='|': self.adv(); self.add('CMD_PIPE','|',p,'|'); continue
            if ch=='?': self.adv(); self.add('CMD_QMARK','?',p,'?'); continue
            if ch=='<':
                self.adv()
                if self.peek()=='<': self.adv(); self.add('CMD_DLESS','<<',p,'<<')
                else: self.add('CMD_LESS','<',p,'<')
                continue
            if ch=='>':
                self.adv()
                if self.peek()=='>': self.adv(); self.add('CMD_DGREAT','>>',p,'>>')
                else: self.add('CMD_GREAT','>',p,'>')
                continue
            word=self.scan_cmd_word()
            if word: self.add('CMD_WORD',word,p,word.raw_display)
        self.err(Pos(self.file,self.line,self.col), 'unexpected end of file.')
    def scan_cmd_word(self):
        p=self.pos(); segs=[]; raw=''; anyq=False
        specials=set(' \t\r\n;|<>?}#')
        while not self.eof():
            ch=self.peek()
            if ch in specials: break
            if ch=="'" or ch=='"':
                quote=ch; anyq=True; raw+=self.adv(); lit=''
                while not self.eof():
                    c=self.adv(); raw+=c
                    if c==quote: break
                    if c=='\\':
                        if self.eof(): break
                        ep=self.pos(); n=self.adv(); raw+=n
                        mp={'n':'\n','t':'\t','0':'\0','\\':'\\','"':'"',"'":"'", '$':'$'}
                        if n in mp: lit+=mp[n]
                        else:
                            self.err(Pos(self.file,ep.line,ep.col-1), f"invalid escape sequence '\\{n}'.")
                    elif quote=='"' and c=='$' and (self.peek().isalpha() or self.peek()=='_'):
                        # previous $ already in raw; parse var name from stream and remove from lit
                        name=''
                        sp=self.pos()
                        while self.peek().isalnum() or self.peek()=='_':
                            name+=self.adv(); raw+=name[-1]
                        if lit:
                            segs.append(CmdSegment('lit',lit,True,p)); lit=''
                        segs.append(CmdSegment('var',name,True,sp))
                        raw = raw[:-len(name)-1] + '${{'+name+'}}'
                    else:
                        lit+=c
                if lit: segs.append(CmdSegment('lit',lit,True,p))
            elif ch=='$' and (self.i+1<len(self.s) and (self.s[self.i+1].isalpha() or self.s[self.i+1]=='_')):
                self.adv(); name=''; sp=self.pos()
                while self.peek().isalnum() or self.peek()=='_': name+=self.adv()
                raw+='${{'+name+'}}'; segs.append(CmdSegment('var',name,False,sp))
            else:
                lit=''
                while not self.eof():
                    c=self.peek()
                    if c in specials or c in ('"',"'") or (c=='$' and self.i+1<len(self.s) and (self.s[self.i+1].isalpha() or self.s[self.i+1]=='_')): break
                    lit+=self.adv()
                raw+=lit; segs.append(CmdSegment('lit',lit,False,p))
        if raw=='': return None
        return CmdWord(segs,raw,anyq)

def escape_unexpected(ch):
    if ch=='\n': return '\\n'
    if ch=='\t': return '\\t'
    if ch=='"': return '\"'
    return ch

