# ----------------------------- parser -----------------------------

class Parser:
    def __init__(self,tokens,filename): self.toks=tokens; self.i=0; self.errors=[]; self.file=filename
    def cur(self): return self.toks[self.i]
    def at(self,*typs): return self.cur().typ in typs
    def adv(self): t=self.cur(); self.i=min(self.i+1,len(self.toks)-1); return t
    def match(self,*typs):
        if self.at(*typs): return self.adv()
        return None
    def expect(self,typ,msg=None):
        if self.at(typ): return self.adv()
        t=self.cur(); self.err(t.pos, msg or f"unexpected '{t.text}', expected {typ}"); return Token(typ,'',t.pos,'')
    def err(self,pos,msg): self.errors.append(Diag(pos,msg,False))
    def parse(self): return self.parse_block(('EOF',))
    def parse_block(self,enders):
        out=[]
        while not self.at(*enders) and not self.at('EOF','RBRACE'):
            st=self.parse_stmt()
            if st is not None: out.append(st)
            else: self.adv()
        return out
    def parse_stmt(self):
        t=self.cur()
        if t.typ=='LET':
            self.adv(); name_tok=self.expect('IDENT','unexpected '+repr_token(self.cur())+', expected identifier')
            # Error message above too pythonic; adjust when needed
            if name_tok.typ!='IDENT': pass
            expr=Literal(t.pos,NIL)
            if self.match('='): expr=self.parse_expr()
            return LetStmt(t.pos,name_tok.val if name_tok.typ=='IDENT' else '***ill-formed***',expr)
        if t.typ=='FUNCTION':
            # named function statement if followed by identifier
            if self.i+1 < len(self.toks) and self.toks[self.i+1].typ=='IDENT':
                self.adv(); name=self.adv(); func=self.parse_function_after_name(t.pos)
                return LetStmt(t.pos,name.val,func)
            expr=self.parse_expr(); return ExprStmt(t.pos,expr)
        if t.typ=='RETURN':
            self.adv()
            if self.at('END','ELSE','ELSEIF','EOF','RBRACE'):
                expr=Literal(t.pos,NIL)
            else: expr=self.parse_expr()
            return ReturnStmt(t.pos,expr)
        if t.typ=='BREAK': self.adv(); return BreakStmt(t.pos)
        if t.typ=='WHILE':
            self.adv(); cond=self.parse_expr(stop=('DO',)); self.expect('DO')
            body=self.parse_block(('END',)); self.expect('END')
            return WhileStmt(t.pos,cond,body)
        if t.typ=='FOR':
            self.adv(); name=self.expect('IDENT','unexpected '+repr_token(self.cur())+', expected identifier')
            self.expect('IN'); it=self.parse_expr(stop=('DO',)); self.expect('DO')
            body=self.parse_block(('END',)); self.expect('END')
            return ForStmt(t.pos,name.val if name.typ=='IDENT' else '***ill-formed***',it,body)
        expr=self.parse_expr()
        if self.match('='):
            if not isinstance(expr,(Var,Field,Index,SelfVar)):
                self.err(pos_of(expr),'invalid assignment')
            rhs=self.parse_expr(); return AssignStmt(pos_of(expr),expr,rhs)
        return ExprStmt(pos_of(expr),expr)
    def parse_function_after_name(self,pos):
        self.expect('('); params=[]
        if not self.at(')'):
            while True:
                if self.at('SELF'):
                    self.err(self.cur().pos,"unexpected 'self', expected identifier"); self.adv()
                else:
                    p=self.expect('IDENT','unexpected '+repr_token(self.cur())+', expected identifier')
                    if p.typ=='IDENT': params.append(p.val)
                if self.match(','):
                    if self.at(')'): break
                    continue
                break
        self.expect(')')
        body=self.parse_block(('END',)); self.expect('END')
        return FunctionExpr(pos,params,body)
    def parse_expr(self, minp=0, stop=()):
        left=self.parse_prefix(stop)
        while True:
            if self.at(*stop) or self.at('EOF','END','ELSE','ELSEIF','THEN','DO','IN','RBRACE','CMD_SEMI','CMD_PIPE',',',']',')',':'):
                break
            op=self.cur().typ
            prec=self.prec(op)
            if prec < minp: break
            tok=self.adv()
            right=self.parse_expr(prec+1,stop)
            left=Binary(tok.pos,left,tok.val,right)
        return left
    def prec(self,op):
        return {'OR':1,'AND':2,'==':3,'!=':3,'<':3,'>':3,'<=':3,'>=':3,'+':4,'-':4,'++':4,'*':5,'/':5,'%':5}.get(op,-1)
    def parse_prefix(self,stop=()):
        t=self.cur()
        if t.typ in ('-','NOT'):
            self.adv(); expr=self.parse_expr(6,stop); node=Unary(t.pos,t.val,expr); return self.parse_postfix(node)
        node=self.parse_primary(stop)
        return self.parse_postfix(node)
    def parse_primary(self,stop=()):
        t=self.cur()
        if t.typ=='NUMBER': self.adv(); return Literal(t.pos,t.val[0],t.val[1])
        if t.typ=='STRING': self.adv(); return Literal(t.pos,t.val)
        if t.typ=='CHAR': self.adv(); return Literal(t.pos,t.val)
        if t.typ=='TRUE': self.adv(); return Literal(t.pos,True)
        if t.typ=='FALSE': self.adv(); return Literal(t.pos,False)
        if t.typ=='NIL': self.adv(); return Literal(t.pos,NIL)
        if t.typ=='IDENT': self.adv(); return Var(t.pos,t.val)
        if t.typ=='SELF': self.adv(); return SelfVar(t.pos)
        if t.typ=='(':
            self.adv(); e=self.parse_expr(); self.expect(')'); return e
        if t.typ=='[': return self.parse_array()
        if t.typ=='AT_LBRACKET': return self.parse_dict()
        if t.typ=='IF': return self.parse_if()
        if t.typ=='FUNCTION':
            self.adv(); return self.parse_function_after_name(t.pos)
        if t.typ in ('LBRACE','CAPTURE_LBRACE','ASYNC_LBRACE'):
            return self.parse_command_block()
        self.err(t.pos, f"unexpected '{t.text}'.")
        self.adv(); return Literal(t.pos,NIL)
    def parse_postfix(self,node):
        while True:
            if self.match('('):
                args=[]
                if not self.at(')'):
                    while True:
                        args.append(self.parse_expr())
                        if self.match(','): continue
                        break
                rp=self.expect(')')
                node=Call(pos_of(node),node,args)
            elif self.match('['):
                key=self.parse_expr(); self.expect(']'); node=Index(pos_of(node),node,key)
            elif self.match('.'):
                name=self.expect('IDENT','unexpected '+repr_token(self.cur())+', expected identifier')
                node=Field(pos_of(node),node,name.val if name.typ=='IDENT' else '***ill-formed***')
            else: break
        return node
    def parse_array(self):
        p=self.adv().pos; items=[]
        if not self.at(']'):
            while True:
                items.append(self.parse_expr())
                if self.match(','):
                    if self.at(']'): break
                    continue
                break
        self.expect(']'); return ArrayLit(p,items)
    def parse_dict(self):
        p=self.adv().pos; items=[]
        if not self.at(']'):
            while True:
                if not self.at('IDENT'):
                    self.err(self.cur().pos, f"unexpected '{self.cur().text}', expected identifier")
                    key='***ill-formed***'; kp=self.cur().pos; self.adv()
                else:
                    kt=self.adv(); key=kt.val; kp=kt.pos
                self.expect(':'); val=self.parse_expr(); items.append((key,val,kp))
                if self.match(','):
                    if self.at(']'): break
                    continue
                break
        self.expect(']'); return DictLit(p,items)
    def parse_if(self):
        p=self.adv().pos; cond=self.parse_expr(stop=('THEN',)); self.expect('THEN')
        then=self.parse_block(('ELSE','ELSEIF','END'))
        else_body=[]
        if self.match('ELSEIF'):
            # build nested if in else
            self.i-=1; elseif_tok=self.adv() # consume again
            cond2=self.parse_expr(stop=('THEN',)); self.expect('THEN')
            then2=self.parse_block(('ELSE','ELSEIF','END'))
            else2=[]
            if self.at('ELSE') or self.at('ELSEIF'):
                # parse rest by fabricating recursively is complex; handle one chain
                if self.match('ELSE'):
                    else2=self.parse_block(('END',));
                elif self.match('ELSEIF'):
                    self.i-=1
                    nested=self.parse_if_from_elseif()
                    else2=[ExprStmt(pos_of(nested),nested)]
            self.expect('END')
            else_body=[ExprStmt(elseif_tok.pos,IfExpr(elseif_tok.pos,cond2,then2,else2))]
            return IfExpr(p,cond,then,else_body)
        if self.match('ELSE'):
            else_body=self.parse_block(('END',))
        self.expect('END'); return IfExpr(p,cond,then,else_body)
    def parse_if_from_elseif(self):
        tok=self.expect('ELSEIF')
        cond=self.parse_expr(stop=('THEN',)); self.expect('THEN')
        then=self.parse_block(('ELSE','ELSEIF','END'))
        else_body=[]
        if self.match('ELSE'):
            else_body=self.parse_block(('END',))
        return IfExpr(tok.pos,cond,then,else_body)
    def parse_command_block(self):
        t=self.adv(); kind={'LBRACE':'normal','CAPTURE_LBRACE':'capture','ASYNC_LBRACE':'async'}[t.typ]
        seqs=[]
        while not self.at('RBRACE','EOF'):
            if self.match('CMD_SEMI'): continue
            pipe=self.parse_pipeline()
            semi=bool(self.match('CMD_SEMI'))
            seqs.append(CommandSeq([pipe],semi))
        self.expect('RBRACE')
        return CommandBlock(t.pos,kind,seqs)
    def parse_pipeline(self):
        stages=[self.parse_simple_command()]
        while self.match('CMD_PIPE'):
            stages.append(self.parse_simple_command())
        return Pipeline(stages)
    def parse_simple_command(self):
        p=self.cur().pos; words=[]; redirs=[]; qmark=False
        while not self.at('CMD_SEMI','CMD_PIPE','RBRACE','EOF'):
            if self.match('CMD_QMARK'):
                qmark=True; continue
            fd=None
            # redir with explicit fd: numeric word immediately before >
            if self.at('CMD_WORD') and is_plain_digits(self.cur().val) and self.i+1<len(self.toks) and self.toks[self.i+1].typ in ('CMD_GREAT','CMD_DGREAT'):
                fd=int(plain_word_text(self.adv().val))
            if self.at('CMD_GREAT','CMD_DGREAT','CMD_LESS','CMD_DLESS'):
                op=self.adv(); target=self.expect('CMD_WORD')
                if target.typ=='CMD_WORD':
                    defaultfd=0 if op.typ in ('CMD_LESS','CMD_DLESS') else 1
                    dup=(op.typ=='CMD_GREAT' and is_plain_digits(target.val))
                    redirs.append(Redir(op.pos, fd if fd is not None else defaultfd, op.val, target.val, dup))
                continue
            if self.at('CMD_WORD'):
                words.append(self.adv().val); continue
            # recover
            self.adv()
        return SimpleCommand(p,words,redirs,qmark)

def repr_token(tok): return f"'{tok.text}'"
def plain_word_text(w):
    s=''
    for seg in w.segments:
        if seg.kind!='lit' or seg.quoted: return ''
        s+=seg.val
    return s
def is_plain_digits(w):
    s=plain_word_text(w); return s.isdigit()

# ----------------------------- AST printer -----------------------------

class AstPrinter:
    def expr(self,e,inline=True,indent=0):
        if isinstance(e,Literal):
            v=e.value
            if v is NIL: return 'nil'
            if isinstance(v,bool): return 'true' if v else 'false'
            if isinstance(v,int) and not isinstance(v,bool): return str(v)
            if isinstance(v,float): return ast_num(v,True)
            if isinstance(v,Char): return "'"+esc_str(v.ch,"'")+"'"
            if isinstance(v,str): return '"'+esc_str(v)+'"'
        if isinstance(e,Var): return e.name
        if isinstance(e,SelfVar): return 'self'
        if isinstance(e,Unary): return f"({e.op if e.op!='not' else 'not'} {self.expr(e.expr,True,indent)})"
        if isinstance(e,Binary): return f"({self.expr(e.left,True,indent)} {e.op} {self.expr(e.right,True,indent)})"
        if isinstance(e,ArrayLit):
            if inline: return '[ ' + ', '.join(self.expr(x,True,indent) for x in e.items) + ' ]' if e.items else '[]'
            if not e.items: return '[]'
            pad='\t'*(indent+1); end='\t'*indent
            return '[\n' + ',\n'.join(pad+self.expr(x,True,indent+1) for x in e.items) + '\n' + end + ']'
        if isinstance(e,DictLit):
            if inline and not e.items: return '@[]'
            if inline:
                return '@[ ' + ', '.join(f'{k}: {self.expr(v,True,indent)}' for k,v,p in e.items) + ' ]' if e.items else '@[]'
            if not e.items: return '@[]'
            pad='\t'*(indent+1); end='\t'*indent
            return '@[\n' + ',\n'.join(pad+f'{k}: {self.expr(v,True,indent+1)}' for k,v,p in e.items) + '\n' + end + ']'
        if isinstance(e,Field): return self.expr(e.obj,True,indent)+'.'+e.name
        if isinstance(e,Index): return self.expr(e.obj,True,indent)+'['+self.expr(e.key,True,indent)+']'
        if isinstance(e,Call): return self.expr(e.callee,True,indent)+'('+', '.join(self.expr(a,True,indent) for a in e.args)+')'
        if isinstance(e,IfExpr):
            if inline and len(e.then_body)==1 and len(e.else_body)<=1 and all(isinstance(x,ExprStmt) for x in e.then_body+e.else_body):
                s=f"if {self.expr(e.cond,True,indent)} then {self.stmt_expr(e.then_body[0],indent)}"
                if e.else_body: s+=f" else {self.stmt_expr(e.else_body[0],indent)}"
                return s+' end'
            pad='\t'*(indent+1); end='\t'*indent
            s=f"if {self.expr(e.cond,True,indent)} then\n"+self.block(e.then_body,indent+1)
            if e.else_body: s+='\n'+end+'else\n'+self.block(e.else_body,indent+1)
            return s+'\n'+end+'end'
        if isinstance(e,FunctionExpr):
            pad='\t'*(indent+1); end='\t'*indent
            body=self.block(e.body,indent+1)
            return f"function({', '.join(e.params)})" + ("\n"+body if body else '') + "\n"+end+'end'
        if isinstance(e,CommandBlock): return self.command(e,indent)
        return '***ill-formed***'
    def stmt_expr(self,st,indent):
        if isinstance(st,ExprStmt): return self.expr(st.expr,True,indent)
        return self.stmt(st,indent).strip()
    def block(self,stmts,indent=0): return '\n'.join(self.stmt(s,indent) for s in stmts)
    def stmt(self,s,indent=0):
        pad='\t'*indent
        if isinstance(s,LetStmt):
            rhs_inline=not isinstance(s.expr,(ArrayLit,DictLit,IfExpr,FunctionExpr,CommandBlock))
            return pad+f"let {s.name} = {self.expr(s.expr,rhs_inline,indent)}"
        if isinstance(s,AssignStmt): return pad+self.expr(s.target,True,indent)+' = '+self.expr(s.expr,True,indent)
        if isinstance(s,ExprStmt): return pad+self.expr(s.expr,False,indent) if isinstance(s.expr,(CommandBlock,FunctionExpr)) else pad+self.expr(s.expr,True,indent)
        if isinstance(s,ReturnStmt): return pad+'return '+self.expr(s.expr,True,indent) if not (isinstance(s.expr,Literal) and s.expr.value is NIL) else pad+'return'
        if isinstance(s,BreakStmt): return pad+'break'
        if isinstance(s,WhileStmt): return pad+f"while {self.expr(s.cond,True,indent)} do\n"+self.block(s.body,indent+1)+'\n'+pad+'end'
        if isinstance(s,ForStmt): return pad+f"for {s.name} in {self.expr(s.iterable,True,indent)} do\n"+self.block(s.body,indent+1)+'\n'+pad+'end'
        return pad+'***ill-formed***'
    def command(self,c,indent=0):
        opener={'normal':'{','capture':'${','async':'&{'}[c.kind]
        pad='\t'*(indent+1); end='\t'*indent
        lines=[]
        for seq in c.commands:
            if not seq.pipelines: continue
            line=self.pipeline(seq.pipelines[0])
            if seq.semi: line+=';'
            lines.append(pad+line)
        if not lines: return opener+'}'
        return opener+'\n'+'\n'.join(lines)+'\n'+end+'}'
    def pipeline(self,p): return ' | '.join(self.simple(st) for st in p.stages)
    def simple(self,cmd):
        parts=[w.ast_display() for w in cmd.words]
        for r in cmd.redirs:
            targ=plain_word_text(r.target) if r.dup else r.target.ast_display()
            op=r.op
            if r.fd==1 and op in ('>','>>'): op=('1>' if op=='>' else '1>>')
            elif r.fd==0 and op=='<': op='<'
            elif r.fd==0 and op=='<<': op='<<'
            else: op=f"{r.fd}{op}"
            parts.append(op+targ)
        if cmd.qmark: parts.append('?')
        return ' '.join(parts)

# ----------------------------- static analyzer -----------------------------

class Scope:
    def __init__(self,parent=None): self.parent=parent; self.names=set()
    def declare(self,n): self.names.add(n)
    def resolve(self,n):
        s=self
        while s:
            if n in s.names: return True
            s=s.parent
        return False

class Analyzer:
    def __init__(self,filename): self.errors=[]; self.filename=filename
    def error(self,pos,msg): self.errors.append(Diag(pos,msg,False))
    def analyze(self,stmts):
        g=Scope(); g.declare('std')
        self.block(stmts,g,False,False)
        return self.errors
    def block(self,stmts,scope,in_func,in_loop):
        for st in stmts: self.stmt(st,scope,in_func,in_loop)
    def stmt(self,st,scope,in_func,in_loop):
        if isinstance(st,LetStmt):
            scope.declare(st.name); self.expr(st.expr,scope,in_func,in_loop)
        elif isinstance(st,AssignStmt):
            self.assign_target(st.target,scope,in_func,in_loop); self.expr(st.expr,scope,in_func,in_loop)
        elif isinstance(st,ExprStmt): self.expr(st.expr,scope,in_func,in_loop)
        elif isinstance(st,ReturnStmt):
            if not in_func: self.error(st.pos,'return statement outside function')
            self.expr(st.expr,scope,in_func,in_loop)
        elif isinstance(st,BreakStmt):
            if not in_loop: self.error(st.pos,'break statement outside loop')
        elif isinstance(st,WhileStmt):
            self.expr(st.cond,scope,in_func,in_loop); self.block(st.body,Scope(scope),in_func,True)
        elif isinstance(st,ForStmt):
            self.expr(st.iterable,scope,in_func,in_loop); sc=Scope(scope); sc.declare(st.name); self.block(st.body,sc,in_func,True)
    def assign_target(self,t,scope,in_func,in_loop):
        if isinstance(t,Var):
            if not scope.resolve(t.name): self.error(t.pos,f"undeclared variable '{t.name}'")
        elif isinstance(t,SelfVar):
            if not in_func: self.error(t.pos,'self keyword outside function')
        elif isinstance(t,Field): self.expr(t.obj,scope,in_func,in_loop)
        elif isinstance(t,Index): self.expr(t.obj,scope,in_func,in_loop); self.expr(t.key,scope,in_func,in_loop)
    def expr(self,e,scope,in_func,in_loop):
        if isinstance(e,Var):
            if not scope.resolve(e.name): self.error(e.pos,f"undeclared variable '{e.name}'")
        elif isinstance(e,SelfVar):
            if not in_func: self.error(e.pos,'self keyword outside function')
        elif isinstance(e,(Literal,)): return
        elif isinstance(e,Unary): self.expr(e.expr,scope,in_func,in_loop)
        elif isinstance(e,Binary): self.expr(e.left,scope,in_func,in_loop); self.expr(e.right,scope,in_func,in_loop)
        elif isinstance(e,ArrayLit):
            for x in e.items: self.expr(x,scope,in_func,in_loop)
        elif isinstance(e,DictLit):
            for k,v,p in e.items: self.expr(v,scope,in_func,in_loop)
        elif isinstance(e,Field): self.expr(e.obj,scope,in_func,in_loop)
        elif isinstance(e,Index): self.expr(e.obj,scope,in_func,in_loop); self.expr(e.key,scope,in_func,in_loop)
        elif isinstance(e,Call): self.expr(e.callee,scope,in_func,in_loop); [self.expr(a,scope,in_func,in_loop) for a in e.args]
        elif isinstance(e,IfExpr):
            self.expr(e.cond,scope,in_func,in_loop); self.block(e.then_body,Scope(scope),in_func,in_loop); self.block(e.else_body,Scope(scope),in_func,in_loop)
        elif isinstance(e,FunctionExpr):
            sc=Scope(scope)
            for p in e.params: sc.declare(p)
            self.block(e.body,sc,True,False)
        elif isinstance(e,CommandBlock):
            for seq in e.commands:
                for pipe in seq.pipelines:
                    for cmd in pipe.stages:
                        for w in cmd.words:
                            for seg in w.segments:
                                if seg.kind=='var' and not scope.resolve(seg.val): self.error(seg.pos or cmd.pos,f"undeclared variable '{seg.val}'")
                        for r in cmd.redirs:
                            for seg in r.target.segments:
                                if seg.kind=='var' and not scope.resolve(seg.val): self.error(seg.pos or r.pos,f"undeclared variable '{seg.val}'")

# ----------------------------- interpreter -----------------------------

class AsyncTask:
    def __init__(self, target):
        self.result=NIL; self.exc=None
        self.th=threading.Thread(target=self._run,args=(target,)); self.th.start()
    def _run(self,target):
        try: self.result=target()
        except Exception as e: self.exc=e
    def join(self):
        self.th.join()
        if self.exc: raise self.exc
        return self.result

class Interpreter:
    def __init__(self, filename='<stdin>', args=None, import_cache=None, stdin=None):
        self.filename=filename; self.args=args or []; self.import_cache=import_cache if import_cache is not None else {}
        self.rand=random.Random(); self.stdin=stdin or sys.stdin
        self.global_env=Env(); self.global_env.declare('std', self.make_std())
    def make_std(self):
        std={}
        def bf(name,func,arity=None,variadic=False): return BuiltinFunction('std.'+name,func,arity,variadic)
        # insert in observed-ish order
        std['range']=bf('range',std_range,3); std['pop']=bf('pop',std_pop,1); std['iter']=bf('iter',std_iter,1)
        std['bytes']=bf('bytes',std_bytes,1); std['is_empty']=bf('is_empty',std_is_empty,1); std['to_string']=bf('to_string',std_to_string,1)
        std['json']={'decode':BuiltinFunction('std.json.decode',std_json_decode,1),'encode':BuiltinFunction('std.json.encode',std_json_encode,1)}
        std['int']=bf('int',std_int,1); std['env']=bf('env',std_env,1); std['read']=bf('read',std_read,1); std['randint']=bf('randint',std_randint,2)
        std['hex']={'decode':BuiltinFunction('std.hex.decode',std_hex_decode,1),'encode':BuiltinFunction('std.hex.encode',std_hex_encode,1)}
        std['rand']=bf('rand',std_rand,0); std['typecheck']=bf('typecheck',std_typecheck,2); std['try_typecheck']=bf('try_typecheck',std_try_typecheck,2)
        std['error']=bf('error',std_error,2); std['cd']=bf('cd',std_cd,1); std['glob']=bf('glob',std_glob,1)
        std['println']=BuiltinFunction('std.println',std_println,None,True); std['len']=bf('len',std_len,1); std['randseed']=bf('randseed',std_randseed,1)
        std['exit']=bf('exit',std_exit,1); std['has_error']=bf('has_error',std_has_error,1); std['panic']=bf('panic',std_panic,1)
        std['substr']=bf('substr',std_substr,3); std['trim']=bf('trim',std_trim,1); std['catch']=bf('catch',std_catch,1); std['cwd']=bf('cwd',std_cwd,0)
        std['split']=bf('split',std_split,2); std['assert']=bf('assert',std_assert,1); std['import']=bf('import',std_import,1)
        std['regex']=bf('regex',std_regex,1); std['export']=bf('export',std_export,2); std['float']=bf('float',std_float,1); std['push']=bf('push',std_push,2)
        std['base64']={'decode':BuiltinFunction('std.base64.decode',std_b64_decode,1),'encode':BuiltinFunction('std.base64.encode',std_b64_encode,1)}
        std['args']=bf('args',std_args,0); std['type']=bf('type',std_type,1); std['contains']=bf('contains',std_contains,2); std['sort']=bf('sort',std_sort,1)
        std['replace']=bf('replace',std_replace,3); std['sleep']=bf('sleep',std_sleep,1); std['print']=BuiltinFunction('std.print',std_print,None,True); std['bind']=bf('bind',std_bind,2)
        return std
    def run(self,stmts, env=None):
        return self.eval_block(stmts, env or self.global_env)
    def eval_block(self,stmts,env):
        val=NIL
        for st in stmts: val=self.eval_stmt(st,env)
        return val
    def eval_stmt(self,st,env):
        if isinstance(st,LetStmt):
            env.declare(st.name,NIL); val=self.eval_expr(st.expr,env); env.set(st.name,val); return val
        if isinstance(st,AssignStmt):
            val=self.eval_expr(st.expr,env); self.assign(st.target,val,env); return val
        if isinstance(st,ExprStmt): return self.eval_expr(st.expr,env)
        if isinstance(st,ReturnStmt): raise ReturnEx(self.eval_expr(st.expr,env))
        if isinstance(st,BreakStmt): raise BreakEx()
        if isinstance(st,WhileStmt):
            last=NIL
            while True:
                c=self.eval_expr(st.cond,env); ensure_bool_cond(c,st.cond)
                if not c: break
                try: last=self.eval_block(st.body,Env(env))
                except BreakEx: break
            return last
        if isinstance(st,ForStmt):
            it=self.eval_expr(st.iterable,env); expect_type(it,'function',st.iterable.pos if hasattr(st.iterable,'pos') else st.pos)
            last=NIL
            while True:
                item=call_function(self,it,[],st.pos)
                if not isinstance(item,dict): panic(st.iterable.pos,f"value ({value_str(item)}) has unexpected type, expected dict")
                fin=index_value(item,'finished',st.pos)
                if fin: break
                val=index_value(item,'value',st.pos)
                sc=Env(env); sc.declare(st.name,val)
                try: last=self.eval_block(st.body,sc)
                except BreakEx: break
            return last
    def assign(self,t,val,env):
        if isinstance(t,Var): env.set(t.name,val); return
        if isinstance(t,SelfVar): env.set('self',val); return
        if isinstance(t,Field):
            obj=self.eval_expr(t.obj,env); assign_index(obj,t.name,val,t.pos); return
        if isinstance(t,Index):
            obj=self.eval_expr(t.obj,env); key=self.eval_expr(t.key,env); assign_index(obj,key,val,t.pos); return
        panic(pos_of(t),'invalid assignment')
    def eval_expr(self,e,env):
        if isinstance(e,Literal): return e.value
        if isinstance(e,Var): return env.get(e.name)
        if isinstance(e,SelfVar): return env.get('self')
        if isinstance(e,Unary):
            v=self.eval_expr(e.expr,env)
            if e.op=='-':
                if isinstance(v,int) and not isinstance(v,bool): return -v
                if isinstance(v,float): return -v
                panic(e.expr.pos,f"value ({value_str(v)}) has unexpected type, expected int or float")
            if e.op=='not':
                expect_type(v,'bool',e.expr.pos); return not v
        if isinstance(e,Binary): return self.eval_binary(e,env)
        if isinstance(e,ArrayLit): return [self.eval_expr(x,env) for x in e.items]
        if isinstance(e,DictLit):
            d={}
            for k,v,p in e.items: d[k]=self.eval_expr(v,env)
            return d
        if isinstance(e,IfExpr):
            c=self.eval_expr(e.cond,env); ensure_bool_cond(c,e.cond)
            return self.eval_block(e.then_body if c else e.else_body,Env(env)) if (c or e.else_body) else NIL
        if isinstance(e,FunctionExpr): return UserFunction(e.params,e.body,env,e.pos)
        if isinstance(e,Field): return index_value(self.eval_expr(e.obj,env),e.name,e.pos)
        if isinstance(e,Index): return index_value(self.eval_expr(e.obj,env),self.eval_expr(e.key,env),e.pos)
        if isinstance(e,Call):
            receiver=NIL
            if isinstance(e.callee,Field):
                receiver=self.eval_expr(e.callee.obj,env); fn=index_value(receiver,e.callee.name,e.callee.pos)
            elif isinstance(e.callee,Index):
                receiver=self.eval_expr(e.callee.obj,env); key=self.eval_expr(e.callee.key,env); fn=index_value(receiver,key,e.callee.pos)
            else: fn=self.eval_expr(e.callee,env)
            args=[self.eval_expr(a,env) for a in e.args]
            return call_function(self,fn,args,e.pos,receiver if isinstance(fn,UserFunction) else NIL)
        if isinstance(e,CommandBlock): return self.eval_command_block(e,env)
        return NIL
    def eval_binary(self,e,env):
        op=e.op
        if op=='and':
            l=self.eval_expr(e.left,env); expect_type(l,'bool',e.left.pos)
            if not l: return False
            r=self.eval_expr(e.right,env); expect_type(r,'bool',e.right.pos); return bool(r)
        if op=='or':
            l=self.eval_expr(e.left,env); expect_type(l,'bool',e.left.pos)
            if l: return True
            r=self.eval_expr(e.right,env); expect_type(r,'bool',e.right.pos); return bool(r)
        l=self.eval_expr(e.left,env); r=self.eval_expr(e.right,env)
        if op in ('+','-','*','/','%'):
            if isinstance(l,int) and not isinstance(l,bool):
                expect_type(r,'int',e.right.pos)
                if op=='+': return l+r
                if op=='-': return l-r
                if op=='*': return l*r
                if op=='/': return int(l/r) if r!=0 else panic(e.pos,'division by zero')
                if op=='%': return l - int(l/r)*r if r!=0 else panic(e.pos,'division by zero')
            if isinstance(l,float):
                expect_type(r,'float',e.right.pos)
                if op=='+': return l+r
                if op=='-': return l-r
                if op=='*': return l*r
                if op=='/': return l/r
                if op=='%': return math.fmod(l,r)
            panic(e.left.pos,f"value ({value_str(l)}) has unexpected type, expected int or float")
        if op=='++':
            expect_type(l,'string',e.left.pos); expect_type(r,'string',e.right.pos); return l+r
        if op in ('==','!='):
            eq=hush_equal(l,r); return eq if op=='==' else not eq
        if op in ('<','<=','>','>='):
            if isinstance(l,int) and not isinstance(l,bool): expect_type(r,'int',e.right.pos)
            elif isinstance(l,float): expect_type(r,'float',e.right.pos)
            elif isinstance(l,str): expect_type(r,'string',e.right.pos)
            elif isinstance(l,Char): expect_type(r,'char',e.right.pos)
            else: panic(e.left.pos,f"value ({value_str(l)}) has unexpected type, expected int, float, string or char")
            return {'<':l<r,'<=':l<=r,'>':l>r,'>=':l>=r}[op]
    def eval_command_block(self,c,env):
        if c.kind=='async':
            return AsyncTask(lambda: self._run_command_prepared(c,env,False))
        return self._run_command_prepared(c,env,c.kind=='capture')
    def _run_command_prepared(self,c,env,capture):
        prepared=[]
        for seq in c.commands:
            for pipe in seq.pipelines:
                stages=[]
                for st in pipe.stages:
                    stages.append(prepare_simple(self,st,env))
                prepared.append((stages, seq.semi))
        return execute_prepared(prepared,capture,c.pos)

def ensure_bool_cond(v,node):
    if not isinstance(v,bool): panic(node.pos, f"condition ({value_str(v)}) is not a boolean")

def hush_equal(a,b):
    if type(a)!=type(b): return False
    if isinstance(a,Char): return a.ch==b.ch
    if isinstance(a,list): return len(a)==len(b) and all(hush_equal(x,y) for x,y in zip(a,b))
    if isinstance(a,dict): return a==b
    return a==b

def call_function(interp,fn,args,pos,receiver=NIL):
    if isinstance(fn,UserFunction): return fn.call(interp,args,pos,receiver)
    if isinstance(fn,BuiltinFunction): return fn.call(interp,args,pos,receiver)
    panic(pos, f"value ({value_str(fn)}) has unexpected type, expected function")

def key_norm(k):
    if isinstance(k,Char): return k.ch
    return k

def index_value(obj,key,pos):
    key=key_norm(key)
    if isinstance(obj,str):
        expect_type(key,'int',pos)
        if key<0 or key>=len(obj): panic(pos,f"index ({value_str(key)}) out of bounds")
        return Char(obj[key])
    if isinstance(obj,list):
        expect_type(key,'int',pos)
        if key<0 or key>=len(obj): panic(pos,f"index ({value_str(key)}) out of bounds")
        return obj[key]
    if isinstance(obj,dict):
        if key in obj: return obj[key]
        panic(pos,f"index ({value_str(key)}) out of bounds")
    if isinstance(obj,HError):
        panic(pos,f"index ({value_str(key)}) out of bounds")
    panic(pos, f"value ({value_str(obj)}) has unexpected type, expected string, array, dict or error")

def assign_index(obj,key,val,pos):
    key=key_norm(key)
    if isinstance(obj,list):
        expect_type(key,'int',pos)
        if key<0 or key>=len(obj): panic(pos,f"index ({value_str(key)}) out of bounds")
        obj[key]=val; return
    if isinstance(obj,dict): obj[key]=val; return
    panic(pos, f"value ({value_str(obj)}) has unexpected type, expected string, array, dict or error")

# ----------------------------- commands -----------------------------

@dataclass
class PreparedCommand:
    argv: List[str]
    redirs: List[Redir]
    qmark: bool
    pos: Pos

@dataclass
class PreparedRedir:
    fd:int; op:str; target:str; dup:bool; pos:Pos

def eval_cmd_word(interp,w,env):
    s=''; quoted_all=True; any_quoted=False; has_unquoted=False
    for seg in w.segments:
        if seg.kind=='lit':
            s+=seg.val
            if not seg.quoted: has_unquoted=True
            any_quoted = any_quoted or seg.quoted
        else:
            val=env.get(seg.val); s+=command_atom(val,seg.pos or Pos(interp.filename,1,0))
            if not seg.quoted: has_unquoted=True
            any_quoted = any_quoted or seg.quoted
    return s, has_unquoted and not any_quoted

def prepare_simple(interp,st,env):
    argv=[]
    for w in st.words:
        txt, glob_ok = eval_cmd_word(interp,w,env)
        expanded=expand_cmd_arg(txt,glob_ok)
        argv.extend(expanded)
    reds=[]
    for r in st.redirs:
        txt,_=eval_cmd_word(interp,r.target,env)
        reds.append(PreparedRedir(r.fd,r.op,txt,r.dup,r.pos))
    return PreparedCommand(argv,reds,st.qmark,st.pos)

def expand_cmd_arg(txt,glob_ok):
    if txt.startswith('~/'):
        txt=os.path.expanduser('~')+txt[1:]
    if glob_ok and has_glob(txt):
        pattern=glob_pattern_from_percent(txt)
        matches=sorted(pyglob.glob(pattern))
        if not matches: return []
        out=[]
        for m in matches:
            if '/' not in txt and not m.startswith('./') and not os.path.isabs(m): out.append('./'+m)
            else: out.append(m)
        return out
    return [txt]

def has_glob(s):
    esc=False
    for ch in s:
        if esc: esc=False; continue
        if ch=='%': esc=True; continue
        if ch in '*?[': return True
    return False

def glob_pattern_from_percent(s):
    out=''; esc=False
    for ch in s:
        if esc:
            out+=re.escape(ch); esc=False
        elif ch=='%': esc=True
        else: out+=ch
    if esc: out+='%'
    return out

def execute_prepared(prepared,capture,pos):
    cap_out=''; cap_err=''; first_err=None
    for stages,semi in prepared:
        if not stages: continue
        status,out,err,err_obj=run_pipeline(stages,capture,pos)
        if capture:
            cap_out+=out; cap_err+=err
        if err_obj is not None:
            if first_err is None: first_err=err_obj
            # stop if none of the failed stages marked ? (approx: final command)
            if not any(s.qmark for s in stages): break
    if capture:
        if first_err:
            data={'stdout':cap_out,'stderr':cap_err,'error':{'status': first_err.data.get('status',127) if isinstance(first_err.data,dict) else 127, 'pos': first_err.data.get('pos',pos.display()) if isinstance(first_err.data,dict) else pos.display()}}
            return HError(first_err.message,data,pos)
        return {'stdout':cap_out,'stderr':cap_err}
    return first_err if first_err else NIL

def run_pipeline(stages,capture,pos):
    procs=[]; prev_stdout=None; files=[]
    err_text=''; out_text=''
    try:
        for idx,st in enumerate(stages):
            if not st.argv:
                continue
            stdin=prev_stdout if prev_stdout is not None else None
            stdout=subprocess.PIPE if (idx < len(stages)-1 or capture) else None
            stderr=subprocess.PIPE if capture else None
            # redirs
            input_data=None
            for r in st.redirs:
                if r.op=='<':
                    f=open(r.target,'rb'); files.append(f); stdin=f
                elif r.op=='<<':
                    input_data=r.target.encode(); stdin=subprocess.PIPE
                elif r.op in ('>','>>'):
                    mode='ab' if r.op=='>>' else 'wb'
                    f=open(r.target,mode); files.append(f)
                    if r.fd==1: stdout=f
                    elif r.fd==2: stderr=f
            try:
                p=subprocess.Popen(st.argv,stdin=stdin,stdout=stdout,stderr=stderr)
            except FileNotFoundError as e:
                return 127,out_text,err_text,HError(str(e),{'status':127,'pos':st.pos.display()},st.pos)
            if input_data is not None:
                try:
                    p.stdin.write(input_data); p.stdin.close()
                except Exception: pass
            if prev_stdout is not None and hasattr(prev_stdout,'close'):
                try: prev_stdout.close()
                except Exception: pass
            prev_stdout=p.stdout if idx < len(stages)-1 else None
            procs.append((p,st))
        if not procs: return 0,'','',None
        # communicate last first, then wait previous
        lastp,lastst=procs[-1]
        out,err=lastp.communicate()
        if capture:
            out_text+=(out or b'').decode(errors='replace')
            err_text+=(err or b'').decode(errors='replace')
        status=lastp.returncode
        for p,st in procs[:-1]:
            _,e=p.communicate()
            if capture and e: err_text+=e.decode(errors='replace')
            if p.returncode!=0 and status==0: status=p.returncode; lastst=st
        if status!=0:
            return status,out_text,err_text,HError('command returned non-zero',{'status':status,'pos':lastst.pos.display()},lastst.pos)
        return status,out_text,err_text,None
    finally:
        for f in files:
            try: f.close()
            except Exception: pass

