# ----------------------------- source runner / program printer -----------------------------

def print_lex(filename, lex_items):
    print('-'*50)
    for it in lex_items:
        if isinstance(it,Diag):
            print(f"Error: line {it.pos.line}, column {it.pos.col} - {it.msg}")
        elif isinstance(it,Token) and it.typ!='EOF':
            print(f"{filename} (line {it.pos.line}, column {it.pos.col}):\t{it.text}")
    print('-'*50)

def print_ast(filename, stmts):
    print('-'*50); print(f"AST for {filename}")
    s=AstPrinter().block(stmts)
    if s: print(s)
    print('-'*50)

def print_program(filename, stmts):
    # A compact program view approximating the original: declarations plus AST-like lowered body.
    print('-'*50); print(f"Program for {filename}")
    names=['std']
    def collect(sts):
        for st in sts:
            if isinstance(st,LetStmt): names.append(st.name)
    collect(stmts)
    for i,n in enumerate(names): print(f"let #{i}: auto")
    # Substitute only global names.
    ap=AstPrinter(); text=ap.block(stmts)
    for i,n in sorted(list(enumerate(names)), key=lambda x:-len(x[1])):
        text=re.sub(r'\b'+re.escape(n)+r'\b', f'#{i}', text)
    if text: print(text)
    print('-'*50)

def run_source(src,filename,args,import_cache=None,execute=True,check=False,stdin=None, modes=None):
    lex=Lexer(src,filename); toks,lexerrs=lex.scan()
    parser=Parser(toks,filename); stmts=parser.parse()
    errors=[]; errors.extend(lexerrs); errors.extend(parser.errors)
    analyzer=Analyzer(filename); static=analyzer.analyze(stmts); errors.extend(static)
    modes=modes or {}
    if modes.get('lex'): print_lex(filename,lex.lex_items)
    if modes.get('ast'): print_ast(filename,stmts)
    if errors:
        # suppress after 20 syntax errors like original, but keep static after; simple print all up to 20 plus note
        count=0; suppressed=0
        for e in errors:
            if count<20:
                print(f"Error: {e.pos.display()} - {e.msg}",file=sys.stderr)
            else: suppressed+=1
            count+=1
        if suppressed: print(f"{suppressed} more supressed syntax errors",file=sys.stderr)
        raise SystemExit(2)
    if modes.get('program'): print_program(filename,stmts)
    if check or not execute: return NIL
    interp=Interpreter(filename,args,import_cache,stdin)
    return interp.run(stmts)

# ----------------------------- CLI -----------------------------

def parse_cli(argv):
    flags={'lex':False,'ast':False,'program':False,'check':False}
    pos=[]; i=0; parsing_flags=True
    while i<len(argv):
        a=argv[i]
        if parsing_flags and a=='--':
            pos.extend(argv[i+1:]); break
        if parsing_flags and a.startswith('-') and a!='-':
            if a in ('-h','--help'): print(HELP,end=''); raise SystemExit(0)
            if a in ('-V','--version'): print(VERSION); raise SystemExit(0)
            if a=='--lex': flags['lex']=True
            elif a=='--ast': flags['ast']=True
            elif a=='--program': flags['program']=True
            elif a=='--check': flags['check']=True
            else:
                print(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n",file=sys.stderr)
                print("USAGE:\n    executable [FLAGS] [arguments]...\n",file=sys.stderr)
